def policy(obs, P):
    x = obs[0]
    v = obs[1]
    theta = obs[2]
    theta_dot = obs[3]
    if abs(x) > P['x_critical']:
        if x > 0:
            return 0
        else:
            return 1
    if abs(x) > P['x_thresh']:
        u = P['k_theta_edge']*theta + P['k_thetadot_edge']*theta_dot - P['k_x_edge']*x - P['k_v_edge']*v
    else:
        u = P['k_theta']*theta + P['k_thetadot']*theta_dot - P['k_x']*x - P['k_v']*v
    if u > P['u_thresh']:
        return 1
    else:
        return 0
